  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Absolute bioavailability of GSK1322322 tablet was 77% after a meal in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib oral bioavailability was estimated at 46% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Linezolid demonstrated 100% absolute oral bioavailability at a 375 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rifapentine absolute bioavailability was 70% after a single 600 mg dose in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paliperidone ER absolute bioavailability was 28% versus IV in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects at steady state.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues have absolute oral bioavailability at or above 28%, with most values between 46% and 100%, supporting F >= 20% for the query.",
  "evidence_gaps": [
    "No direct experimental measurement for the query molecule is available.",
    "Query structure and physicochemical prior are omitted, limiting full transferability assessment.",
    "Encainide shows wide interindividual variability with some reported values below 20%, though mean values remain above threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

